import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Course, CourseService, Lesson } from '../../../core/services/course.service';

@Component({
  selector: 'app-course-detail',
  templateUrl: './course-detail.component.html',
  styleUrls: ['./course-detail.component.css']
})
export class CourseDetailComponent {
  course: Course | undefined;

  constructor(
    private readonly route: ActivatedRoute,
    private readonly router: Router,
    private readonly courseService: CourseService
  ) {
    const id = this.route.snapshot.paramMap.get('id');
    if (id) {
      this.course = this.courseService.getCourseById(id);
    }
  }

  openLesson(lesson: Lesson) {
    if (!this.course) return;
    this.router.navigate(['/courses', this.course.id, 'lessons', lesson.id]);
  }
}
<section class="page" *ngIf="course as c; else notFound">
  <header class="page-header">
    <div>
      <div class="pill">{{ c.level | titlecase }} · ~ {{ c.estimatedWeeks }} weeks</div>
      <h1>{{ c.title }}</h1>
      <p class="page-subtitle">
        {{ c.description }}
      </p>
    </div>

    <a routerLink="/courses" class="back-link">← Back to all courses</a>
  </header>

  <section class="layout">
    <div class="layout-main card">
      <h2>Lessons</h2>
      <p class="layout-subtitle">
        Use this section to link to actual lesson content: GitHub repos, StackBlitz projects,
        Notion pages or a markdown CMS.
      </p>

      <ul class="lessons-list">
        <li *ngFor="let lesson of c.lessons">
          <div class="lesson-main">
            <h3>{{ lesson.title }}</h3>
            <p class="lesson-meta">
              {{ lesson.level | titlecase }} · {{ lesson.duration }}
            </p>
          </div>
          <button class="btn-primary" (click)="openLesson(lesson)">
            Open lesson
          </button>
        </li>
      </ul>
    </div>

    <aside class="layout-side card">
      <h3>Topics covered</h3>
      <ul class="topics">
        <li *ngFor="let topic of c.topics">• {{ topic }}</li>
      </ul>

      <h3 class="mt">How to extend this page</h3>
      <ul class="side-tips">
        <li>Add a progress tracker using localStorage or an API.</li>
        <li>Link each lesson to a YouTube video or live coding session.</li>
        <li>Load course definitions from JSON or a backend.</li>
      </ul>
    </aside>
  </section>
</section>

<ng-template #notFound>
  <section class="page">
    <p>Course not found. <a routerLink="/courses" class="back-link">Back to courses</a></p>
  </section>
</ng-template>
